public class AuthorizeSimulation extends Simulation {

    private static final int RATE = Integer.getInteger("rateRps", 200);
    private static final int SECONDS = Integer.getInteger("durationSec", 180);

    ScenarioBuilder authorize = scenario("authorize")
        .exec(http("POST /authorizations")
            .post("/api/v1/authorizations")
            .header("Idempotency-Key", session -> UUID.randomUUID().toString())
            .body(StringBody("""
                {"accountId":"#{accountId}","currency":"GBP","amountMinor":1299}"""))
            .check(status().in(201, 409)));

    {
        // Open model: arrivals do not wait for responses, so a stall shows up
        // in the percentiles instead of quietly throttling the load.
        setUp(authorize.injectOpen(constantUsersPerSec(RATE).during(SECONDS)))
            .protocols(http.baseUrl("http://localhost:8082"));
    }
}
